import { z } from 'zod';

/**
 * RAG evaluation dataset schema (Fase 7).
 *
 * One JSON object per line in `eval/qa.jsonl`. No personal data is allowed
 * in any field: questions are generic product/policy queries, and answers
 * are checked against `mustContain` facts that come from the synthetic
 * corpus (never prices or stock generated by an LLM).
 */

export const evalCaseTypeSchema = z.enum([
  'answerable',
  'unanswerable',
  'adversarial',
  'compatibility',
  'recommendation',
]);

export type EvalCaseType = z.output<typeof evalCaseTypeSchema>;

const syntheticProductSchema = z.object({
  /** Stable synthetic id (UUID format so online runs stay realistic). */
  id: z.uuid(),
  name: z.string().min(1),
  /** Price in the minor unit + ISO code (mirrors the SQL product row). */
  priceAmount: z.number().int().nonnegative(),
  currency: z.string().regex(/^[A-Z]{3}$/),
  inStock: z.boolean(),
});

export type EvalProduct = z.output<typeof syntheticProductSchema>;

/**
 * One synthetic evidence chunk contributed by a case to the shared eval
 * corpus. The harness pools every case's chunks (so unrelated cases act as
 * realistic distractors) and retrieves over that pool.
 */
const corpusChunkSchema = z.object({
  id: z.string().min(1),
  documentId: z.string().min(1),
  title: z.string().min(1),
  docType: z.enum(['SPEC_SHEET', 'MANUAL', 'FAQ', 'WARRANTY', 'REVIEW', 'POLICY']),
  locale: z.enum(['es', 'en']),
  /** Chunk text. Must contain the case's `mustContain` facts verbatim. */
  content: z.string().min(1),
});

export type EvalCorpusChunk = z.output<typeof corpusChunkSchema>;

export const evalCaseSchema = z
  .object({
    id: z.string().min(1),
    type: evalCaseTypeSchema,
    locale: z.enum(['es', 'en']),
    question: z.string().min(1).max(1000),
    /** Product context for product-scoped cases (synthetic UUID). */
    productId: z.uuid().optional(),
    /** Chunk ids the retriever should return (empty for unanswerable). */
    expectedChunkIds: z.array(z.string().min(1)).default([]),
    /** Document ids the citations should point to. */
    expectedDocIds: z.array(z.string().min(1)).default([]),
    /** Words/facts (lowercased substring match) that must appear. */
    mustContain: z.array(z.string().min(1)).default([]),
    /** Substrings that must NOT appear (injection leakage, prices...). */
    mustNotContain: z.array(z.string().min(1)).default([]),
    /** True when the correct behavior is abstaining. */
    expectAbstention: z.boolean().default(false),
    /** Citations required (false only for abstention cases). */
    citationRequired: z.boolean().default(true),
    /** Recommendation cases: the only product ids allowed in the answer. */
    allowedProductIds: z.array(z.uuid()).default([]),
    /** Compatibility cases: deterministic verdict the answer must state. */
    expectedVerdict: z.enum(['compatible', 'incompatible']).optional(),
    /** Recommendation cases: closed candidate set (simulates SQL hydration). */
    products: z.array(syntheticProductSchema).default([]),
    /** Evidence chunks this case contributes to the shared corpus. */
    corpus: z.array(corpusChunkSchema).default([]),
    notes: z.string().optional(),
  })
  .refine((c) => (c.expectAbstention ? c.mustContain.length === 0 : true), {
    error: 'abstention cases must not require mustContain facts',
  })
  .refine((c) => (c.expectAbstention ? !c.citationRequired : true), {
    error: 'abstention cases must set citationRequired to false',
  });

export type EvalCase = z.output<typeof evalCaseSchema>;

/** Parses one JSONL line (1-based `lineNo` for legible errors). */
export function parseEvalCaseLine(line: string, lineNo: number): EvalCase {
  let raw: unknown;
  try {
    raw = JSON.parse(line) as unknown;
  } catch {
    throw new Error(`eval/qa.jsonl line ${String(lineNo)}: invalid JSON`);
  }
  const parsed = evalCaseSchema.safeParse(raw);
  if (!parsed.success) {
    const rawRecord = raw as { id?: unknown };
    const label = typeof rawRecord.id === 'string' ? rawRecord.id : '?';
    throw new Error(
      `eval/qa.jsonl line ${String(lineNo)} (${label}): ${z.prettifyError(parsed.error)}`,
    );
  }
  return parsed.data;
}

/** Per-case outcome recorded in the results JSON. */
export const evalCaseResultSchema = z.object({
  id: z.string(),
  type: evalCaseTypeSchema,
  locale: z.enum(['es', 'en']),
  /** Null when the case expects no chunks (abstention / recommendation). */
  recalledAtK: z.number().nullable(),
  reciprocalRank: z.number().nullable(),
  retrievedChunkIds: z.array(z.string()),
  abstained: z.boolean(),
  abstentionCorrect: z.boolean(),
  factsFound: z.number(),
  factsTotal: z.number(),
  citationsValid: z.boolean(),
  citationsCount: z.number(),
  hallucinated: z.boolean(),
  hallucinationDetail: z.string().nullable(),
  latencyMs: z.number(),
});

export type EvalCaseResult = z.output<typeof evalCaseResultSchema>;

/** Aggregate report written to `eval/results/<date>-<model>.json`. */
export const evalReportSchema = z.object({
  version: z.literal(1),
  createdAt: z.string(),
  dataset: z.object({
    path: z.string(),
    cases: z.number(),
    byType: z.record(z.string(), z.number()),
    byLocale: z.record(z.string(), z.number()),
  }),
  providers: z.object({
    llmProvider: z.string(),
    llmModel: z.string(),
    embeddingProvider: z.string(),
    embeddingModel: z.string(),
    offline: z.boolean(),
  }),
  retrievalK: z.number(),
  metrics: z.object({
    recallAtK: z.number(),
    mrr: z.number(),
    abstentionAccuracy: z.number(),
    citationValidityRate: z.number(),
    hallucinationRate: z.number(),
    factCoverage: z.number(),
    latencyP50Ms: z.number(),
    latencyP95Ms: z.number(),
  }),
  thresholds: z.object({
    maxHallucinationRate: z.number(),
    minAbstentionAccuracy: z.number(),
    minCitationValidityRate: z.number(),
  }),
  thresholdsPassed: z.boolean(),
  cases: z.array(evalCaseResultSchema),
});

export type EvalReport = z.output<typeof evalReportSchema>;
